// Builds two branded HTML emails: the internal notification (with the
// enrichment section: Apollo profile, LinkedIn, company data and the web
// research brief) and the auto-reply to the submitter. Branding comes from
// the Workflow Configuration node, so you should not need to edit this code.
const cfg  = $('Set — Workflow Configuration').first().json;
const lead = $('Code — Build Enrichment Profile').first().json;

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/\n/g, '<br>');
const escAttr = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const stripUrl = (u) => String(u || '').replace(/^https?:\/\/(www\.)?/i, '').replace(/\/$/, '');
const safeHref = (u) => /^(https?:\/\/|mailto:|tel:)/i.test(String(u || '')) ? String(u) : '';

const LOGO_URL      = cfg.logoUrl;
const BRAND_NAME    = esc(cfg.brandName);
const BRAND_WEBSITE = esc(cfg.brandWebsite);
const COLOR_HEADER  = cfg.colorHeader || '#004080';
const COLOR_ACCENT  = cfg.colorAccent || '#ffc107';
const COLOR_BUTTON  = cfg.colorButton || '#008080';

const name    = esc(lead.name);
const email   = esc(lead.email);
const phone   = esc(lead.phone);
const message = esc(lead.message);
const when    = esc(lead.date + (lead.time ? ' at ' + lead.time : ''));
const category = esc(lead.category);
const urgency  = esc(lead.urgency);
const summary  = esc(lead.summary);
const source   = esc(lead.source);

const urgencyColor = lead.urgency === 'High' ? '#c62828' : lead.urgency === 'Low' ? '#6c757d' : COLOR_BUTTON;

const row = (label, value) =>
  '<tr>'
  + '<td width="130" style="padding:10px 12px;background-color:#e8f0fb;border-radius:4px 0 0 4px;font-size:13px;font-weight:bold;color:' + COLOR_HEADER + ';vertical-align:top;">' + label + '</td>'
  + '<td style="padding:10px 14px;background-color:#f9fbff;border-radius:0 4px 4px 0;font-size:14px;color:#1a1a1a;vertical-align:top;line-height:1.6;">' + value + '</td>'
  + '</tr>'
  + '<tr><td colspan="2" style="height:6px;"></td></tr>';

const link = (url, label) => {
  const href = safeHref(url);
  if (!href) return esc(label || url);
  return '<a href="' + escAttr(href) + '" style="color:' + COLOR_BUTTON + ';text-decoration:none;">' + esc(label || stripUrl(url)) + '</a>';
};
const btn = (href, label, color) =>
  '<a href="' + escAttr(href) + '" style="display:inline-block;background-color:' + color + ';color:#ffffff;text-decoration:none;font-size:14px;font-weight:bold;padding:12px 26px;border-radius:5px;letter-spacing:0.5px;margin:4px 5px;">' + label + '</a>';

const shell = (headline, inner, footerNote) =>
  '<div style="margin:0;padding:0;background-color:#f4f6f9;font-family:Arial,Helvetica,sans-serif;">'
  + '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#f4f6f9;">'
  + '<tr><td align="center" style="padding:30px 15px;">'
  + '<table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;">'
  + '<tr><td align="center" style="background-color:' + COLOR_HEADER + ';padding:28px 30px 20px 30px;border-radius:8px 8px 0 0;">'
  + '<img src="' + LOGO_URL + '" alt="' + BRAND_NAME + '" width="200" style="display:block;max-width:200px;height:auto;margin:0 auto 12px auto;">'
  + '<p style="margin:0;color:#ffffff;font-size:13px;letter-spacing:1px;text-transform:uppercase;">' + headline + '</p>'
  + '</td></tr>'
  + '<tr><td style="background-color:' + COLOR_ACCENT + ';height:4px;"></td></tr>'
  + '<tr><td style="background-color:#ffffff;padding:32px 36px;">' + inner + '</td></tr>'
  + '<tr><td style="background-color:' + COLOR_HEADER + ';padding:18px 30px;border-radius:0 0 8px 8px;text-align:center;">'
  + '<p style="margin:0;font-size:12px;color:#a8c4e0;">' + BRAND_NAME + ' &bull; ' + BRAND_WEBSITE + '</p>'
  + '<p style="margin:6px 0 0 0;font-size:11px;color:#6a93bb;">' + footerNote + '</p>'
  + '</td></tr>'
  + '</table></td></tr></table></div>';

// ---------- About the submitter (Apollo match + web research) ----------
const en   = lead.enrichment || {};
const ap   = en.apollo || {};
const apCo = ap.company || {};
const rs   = en.research || {};
const rp   = rs.person || {};
const rc   = rs.company || {};
const linkedinUrl = ap.linkedinUrl || rp.linkedinUrl || '';

let aboutRows = '';
if (ap.found) {
  const roleLine = [ap.title, apCo.name].filter(Boolean).join(' at ');
  if (roleLine) aboutRows += row('Role', esc(roleLine));
  if (ap.headline && ap.headline !== ap.title) aboutRows += row('Headline', esc(ap.headline));
  if (ap.seniority || ap.departments) aboutRows += row('Seniority', [ap.seniority, ap.departments].filter(Boolean).map(esc).join(' &middot; '));
  if (ap.location) aboutRows += row('Location', esc(ap.location));
  if (linkedinUrl) aboutRows += row('LinkedIn', link(linkedinUrl));
  const coBits = [
    apCo.industry,
    apCo.employees ? apCo.employees + ' employees' : '',
    apCo.founded ? 'founded ' + apCo.founded : '',
    apCo.location
  ].filter(Boolean).map(esc).join(' &bull; ');
  if (apCo.name) {
    aboutRows += row('Company',
      esc(apCo.name)
      + (apCo.website ? ' &nbsp;(' + link(apCo.website) + ')' : '')
      + (coBits ? '<br><span style="font-size:12px;color:#666;">' + coBits + '</span>' : ''));
  }
  if (apCo.description) aboutRows += row('About company', esc(apCo.description));
  if (apCo.phone) aboutRows += row('Company phone', esc(apCo.phone));
  aboutRows += row('Apollo', (ap.profileUrl ? link(ap.profileUrl, 'Open profile in Apollo') : 'Matched') + (ap.matchConfidence ? ' <span style="font-size:12px;color:#666;">(' + esc(ap.matchConfidence) + ' confidence match)</span>' : ''));
} else if (rs.found) {
  // Apollo had no match (or is switched off); fall back to what the web research found.
  const roleLine = [rp.currentTitle, rp.company || rc.name].filter(Boolean).join(' at ');
  if (roleLine) aboutRows += row('Role', esc(roleLine));
  if (rp.location) aboutRows += row('Location', esc(rp.location));
  if (linkedinUrl) aboutRows += row('LinkedIn', link(linkedinUrl));
  const coBits = [rc.industry, rc.sizeEstimate, rc.headquarters].filter(Boolean).map(esc).join(' &bull; ');
  if (rc.name || rc.website) {
    aboutRows += row('Company',
      esc(rc.name || stripUrl(rc.website))
      + (rc.website ? ' &nbsp;(' + link(rc.website) + ')' : '')
      + (coBits ? '<br><span style="font-size:12px;color:#666;">' + coBits + '</span>' : ''));
  }
  if (rc.description) aboutRows += row('About company', esc(rc.description));
  if (ap.attempted && !ap.error) aboutRows += row('Apollo', '<span style="color:#666;">No match found</span>');
}
if (ap.error) aboutRows += row('Apollo', '<span style="color:#c62828;">Lookup failed: ' + esc(ap.error).slice(0, 160) + '</span>');

let researchBlock = '';
if (rs.found) {
  const facts = (rs.notableFacts || []).slice(0, 5)
    .map((f) => '<li style="margin:0 0 4px 0;">' + esc(f) + '</li>').join('');
  const srcs = (rs.sources || []).slice(0, 5)
    .map((s) => '<li style="margin:0 0 3px 0;">' + link(s.url, s.title && s.title !== s.url ? s.title : stripUrl(s.url)) + '</li>').join('');
  researchBlock =
    '<p style="margin:18px 0 6px 0;font-size:13px;font-weight:bold;color:' + COLOR_HEADER + ';">Found online'
    + (rs.confidence ? ' <span style="font-weight:normal;color:#777;">(' + esc(rs.confidence) + ' confidence)</span>' : '') + '</p>'
    + '<p style="margin:0 0 8px 0;font-size:14px;color:#333;line-height:1.6;">' + esc(rs.summary) + '</p>'
    + (facts ? '<ul style="margin:0 0 8px 18px;padding:0;font-size:13px;color:#333;line-height:1.5;">' + facts + '</ul>' : '')
    + (srcs ? '<p style="margin:8px 0 2px 0;font-size:12px;color:#777;">Sources</p><ul style="margin:0 0 0 18px;padding:0;font-size:12px;line-height:1.5;">' + srcs + '</ul>' : '');
} else if (rs.error) {
  researchBlock = '<p style="margin:14px 0 0 0;font-size:12px;color:#c62828;">Web research failed: ' + esc(rs.error).slice(0, 160) + '</p>';
}

const enrichmentAttempted = ap.attempted || rs.attempted;
let aboutSection = '';
if (aboutRows || researchBlock) {
  aboutSection =
    '<p style="margin:26px 0 10px 0;font-size:15px;color:' + COLOR_HEADER + ';font-weight:bold;border-bottom:2px solid ' + COLOR_ACCENT + ';padding-bottom:6px;">About ' + name + '</p>'
    + (aboutRows ? '<table width="100%" cellpadding="0" cellspacing="0" border="0">' + aboutRows + '</table>' : '')
    + researchBlock;
} else if (enrichmentAttempted) {
  aboutSection = '<p style="margin:26px 0 0 0;font-size:13px;color:#777;">No additional information about this submitter was found in Apollo or online.</p>';
}

// ---------- Internal notification ----------
const buttons =
  btn('mailto:' + lead.email, 'Reply to ' + name, COLOR_BUTTON)
  + (ap.profileUrl ? btn(ap.profileUrl, 'View in Apollo', COLOR_HEADER) : '')
  + (safeHref(linkedinUrl) ? btn(linkedinUrl, 'LinkedIn', '#0a66c2') : '');

const notificationInner =
  '<p style="margin:0 0 6px 0;font-size:16px;color:' + COLOR_HEADER + ';font-weight:bold;">You have received a new contact form submission.</p>'
  + '<p style="margin:0 0 22px 0;font-size:13px;color:#555;">'
  + '<span style="display:inline-block;padding:3px 10px;border-radius:12px;background-color:' + COLOR_HEADER + ';color:#fff;font-weight:bold;">' + category + '</span> '
  + '<span style="display:inline-block;padding:3px 10px;border-radius:12px;background-color:' + urgencyColor + ';color:#fff;font-weight:bold;">' + urgency + ' priority</span>'
  + '</p>'
  + (summary ? '<p style="margin:0 0 22px 0;padding:12px 14px;background-color:#fff8e1;border-left:4px solid ' + COLOR_ACCENT + ';font-size:14px;color:#333;"><strong>AI summary:</strong> ' + summary + '</p>' : '')
  + '<table width="100%" cellpadding="0" cellspacing="0" border="0">'
  + row('Name', name)
  + row('Email', '<a href="mailto:' + email + '" style="color:' + COLOR_BUTTON + ';text-decoration:none;">' + email + '</a>')
  + row('Phone', '<a href="tel:' + phone + '" style="color:' + COLOR_BUTTON + ';text-decoration:none;">' + phone + '</a>')
  + row('Date / Time', when)
  + row('Source', source)
  + row('Message', message)
  + '</table>'
  + aboutSection
  + '<div style="text-align:center;margin-top:28px;">' + buttons + '</div>';

const notificationHtml = shell('New Website Inquiry', notificationInner,
  'This notification was sent automatically from your website contact form.');

// ---------- Auto-reply to the submitter ----------
const autoReplyInner =
  '<p style="margin:0 0 16px 0;font-size:16px;color:' + COLOR_HEADER + ';font-weight:bold;">Hi ' + name + ',</p>'
  + '<p style="margin:0 0 22px 0;font-size:14px;color:#333;line-height:1.6;">' + esc(cfg.autoReplyMessage) + '</p>'
  + '<p style="margin:0 0 8px 0;font-size:13px;color:#555;">For your records, here is what you sent us:</p>'
  + '<div style="padding:14px 16px;background-color:#f9fbff;border-radius:6px;font-size:14px;color:#1a1a1a;line-height:1.6;">' + message + '</div>'
  + '<p style="margin:22px 0 0 0;font-size:14px;color:#333;">Kind regards,<br><strong>' + BRAND_NAME + '</strong></p>';

const autoReplyHtml = shell('We received your message', autoReplyInner,
  'This is an automated confirmation. Please do not reply to this email if it came from a no-reply address.');

const autoReplySubject = (cfg.autoReplySubject || 'Thanks for contacting us');

// ---------- vCard attachments ----------
// leadCard: the submitter's details (plus title, company and LinkedIn when
// enrichment found them), attached to the internal notification.
// companyCard: your contact (from Workflow Configuration), attached to the auto-reply.
const vEsc = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const vcard = (c) => {
  const first = c.firstName || '', last = c.lastName || '';
  const full  = (c.fullName || (first + ' ' + last)).trim() || 'Unknown';
  const lines = ['BEGIN:VCARD', 'VERSION:3.0',
    'N:' + vEsc(last) + ';' + vEsc(first) + ';;;',
    'FN:' + vEsc(full)];
  if (c.organization) lines.push('ORG:' + vEsc(c.organization));
  if (c.title)        lines.push('TITLE:' + vEsc(c.title));
  if (c.phone)        lines.push('TEL;TYPE=WORK,VOICE:' + vEsc(c.phone));
  if (c.email)        lines.push('EMAIL;TYPE=INTERNET,WORK:' + vEsc(c.email));
  if (c.website)      lines.push('URL:' + vEsc(c.website));
  if (c.linkedin)     lines.push('X-SOCIALPROFILE;TYPE=linkedin:' + vEsc(c.linkedin));
  if (c.note)         lines.push('NOTE:' + vEsc(c.note));
  lines.push('REV:' + new Date().toISOString(), 'END:VCARD');
  return lines.join('\r\n') + '\r\n';
};
const safeFile = (s) => String(s || 'contact').replace(/[^a-z0-9]+/gi, '_').replace(/^_+|_+$/g, '') || 'contact';

const leadCard = vcard({
  firstName: lead.firstName || String(lead.name || '').trim().split(/\s+/)[0] || '',
  lastName: lead.lastName || '',
  fullName: lead.name,
  organization: lead.company || '',
  title: lead.title || '',
  phone: lead.phone === '(not provided)' ? '' : lead.phone,
  email: lead.email,
  website: lead.website || '',
  linkedin: linkedinUrl,
  note: 'Website inquiry via ' + (lead.source || 'contact form') + ' on ' + lead.date + (lead.summary ? ' - ' + lead.summary : '')
});
const cc = cfg.companyCard || {};
const companyCard = vcard(cc);
const companyFull = (cc.fullName || ((cc.firstName || '') + ' ' + (cc.lastName || ''))).trim();

const binary = {};
if (cfg.attachLeadCard !== false) {
  binary.leadCard = { data: Buffer.from(leadCard, 'utf8').toString('base64'), fileName: safeFile(lead.name) + '.vcf', mimeType: 'text/vcard' };
}
if (cfg.attachCompanyCard !== false) {
  binary.companyCard = { data: Buffer.from(companyCard, 'utf8').toString('base64'), fileName: safeFile(companyFull) + '.vcf', mimeType: 'text/vcard' };
}

return [{ json: { ...lead, notificationHtml, autoReplyHtml, autoReplySubject }, binary }];

// Merges the Apollo match and the web research into one enrichment block
// and passes the full lead record forward. Every path converges here
// (new lead, spam, rejected, enrichment switched off, or an API failure),
// so downstream nodes can rely on the same fields always existing, even
// when they are empty. Nothing here needs editing.
const lead = $('Set — Assemble Lead Record').first().json;

// Returns the first output item of a node, or null when that node did not
// run in this execution (branch skipped) or returned nothing.
const outputOf = (nodeName) => {
  try {
    const n = $(nodeName);
    if (!n.isExecuted) return null;
    const item = n.first();
    return item && item.json ? item.json : null;
  } catch (e) {
    return null;
  }
};
const errorText = (j) => {
  if (!j || !j.error) return '';
  return typeof j.error === 'string' ? j.error : (j.error.message || j.error.description || JSON.stringify(j.error));
};
const joinParts = (...parts) => parts.filter(Boolean).join(', ');
const stripUrl = (u) => String(u || '').replace(/^https?:\/\/(www\.)?/i, '').replace(/\/$/, '');

// ---------- Apollo people match ----------
const apolloRaw = outputOf('Apollo — Enrich Person');
const person = apolloRaw && apolloRaw.person ? apolloRaw.person : null;
const org = person && person.organization ? person.organization : {};

const apollo = {
  attempted: apolloRaw !== null,
  found: !!person,
  id: person ? (person.id || '') : '',
  profileUrl: person && person.id ? 'https://app.apollo.io/#/people/' + person.id : '',
  fullName: person ? (person.name || [person.first_name, person.last_name].filter(Boolean).join(' ')) : '',
  title: person ? (person.title || '') : '',
  headline: person ? (person.headline || '') : '',
  seniority: person ? (person.seniority || '') : '',
  departments: person && Array.isArray(person.departments) ? person.departments.join(', ') : '',
  linkedinUrl: person ? (person.linkedin_url || '') : '',
  twitterUrl: person ? (person.twitter_url || '') : '',
  githubUrl: person ? (person.github_url || '') : '',
  location: person ? joinParts(person.city, person.state, person.country) : '',
  photoUrl: person ? (person.photo_url || '') : '',
  matchConfidence: person ? (person.match_confidence || '') : '',
  company: {
    name: org.name || '',
    website: org.website_url || '',
    domain: org.primary_domain || '',
    linkedinUrl: org.linkedin_url || '',
    industry: org.industry || '',
    employees: org.estimated_num_employees ? String(org.estimated_num_employees) : '',
    founded: org.founded_year ? String(org.founded_year) : '',
    phone: org.phone || org.sanitized_phone || '',
    description: org.short_description || '',
    location: joinParts(org.city, org.state, org.country),
    logoUrl: org.logo_url || ''
  },
  error: errorText(apolloRaw)
};

// ---------- Web research (Perplexity) ----------
const pplxRaw = outputOf('Perplexity — Research Submitter');
let researchText = '';
let foundSources = [];

const pushSource = (s) => {
  if (!s) return;
  if (typeof s === 'string') { foundSources.push({ title: s, url: s }); return; }
  if (s.url) foundSources.push({ title: s.title || s.url, url: s.url });
};

if (pplxRaw) {
  if (typeof pplxRaw.output_text === 'string') researchText = pplxRaw.output_text;
  else if (typeof pplxRaw.text === 'string') researchText = pplxRaw.text;

  if (Array.isArray(pplxRaw.output)) {
    for (const item of pplxRaw.output) {
      if (!item) continue;
      if (item.type === 'message' && Array.isArray(item.content)) {
        for (const c of item.content) {
          if (c && typeof c.text === 'string' && !researchText) researchText = c.text;
        }
      }
      if (item.type === 'search_results' && Array.isArray(item.results)) item.results.forEach(pushSource);
    }
  }
  [pplxRaw.citations, pplxRaw.search_results, pplxRaw.sources].forEach((list) => {
    if (Array.isArray(list)) list.forEach(pushSource);
  });
}

let research = {
  attempted: pplxRaw !== null,
  found: false,
  summary: '',
  person: {},
  company: {},
  notableFacts: [],
  confidence: '',
  sources: [],
  error: errorText(pplxRaw)
};

if (researchText) {
  let parsed = null;
  try { parsed = JSON.parse(researchText); } catch (e) {
    const m = researchText.match(/\{[\s\S]*\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
  }
  if (parsed && typeof parsed === 'object') {
    research.found = !!parsed.summary;
    research.summary = String(parsed.summary || '');
    research.person = parsed.person && typeof parsed.person === 'object' ? parsed.person : {};
    research.company = parsed.company && typeof parsed.company === 'object' ? parsed.company : {};
    research.notableFacts = Array.isArray(parsed.notableFacts) ? parsed.notableFacts.map(String) : [];
    research.confidence = String(parsed.confidence || '');
    if (Array.isArray(parsed.sources)) parsed.sources.forEach(pushSource);
  } else {
    // The model answered in prose instead of JSON; keep it as the summary.
    research.found = true;
    research.summary = researchText.slice(0, 1500);
  }
}

// De-duplicate sources and keep the list short for the email.
const seen = new Set();
for (const s of foundSources) {
  const u = String(s.url || '').trim();
  if (!u || seen.has(u)) continue;
  seen.add(u);
  research.sources.push({ title: s.title || u, url: u });
}
research.sources = research.sources.slice(0, 8);

// ---------- Flattened "best available" fields for the log and the email ----------
const rp = research.person || {};
const rc = research.company || {};
const company     = apollo.company.name || rc.name || rp.company || '';
const title       = apollo.title || rp.currentTitle || '';
const location    = apollo.location || rp.location || '';
const linkedinUrl = apollo.linkedinUrl || rp.linkedinUrl || '';
const website     = apollo.company.website || rc.website || (lead.emailDomain ? 'https://' + lead.emailDomain : '');

return [{ json: {
  ...lead,
  company,
  title,
  location,
  linkedinUrl,
  website: website ? (/^https?:\/\//i.test(website) ? website : 'https://' + stripUrl(website)) : '',
